/// Verifies that a buffer of bytes contains a `SSY`
/// and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_ssy_unchecked`.
#[inline]
pub fn root_as_ssy(buf: &[u8]) -> Result<SSY<'_>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::root::<SSY>(buf)
}

/// Verifies that a buffer of bytes contains a size prefixed
/// `SSY` and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `size_prefixed_root_as_ssy_unchecked`.
#[inline]
pub fn size_prefixed_root_as_ssy(buf: &[u8]) -> Result<SSY<'_>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::size_prefixed_root::<SSY>(buf)
}

/// Verifies, with the given options, that a buffer of bytes
/// contains a `SSY` and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_ssy_unchecked`.
#[inline]
pub fn root_as_ssy_with_opts<'b, 'o>(
    opts: &'o ::flatbuffers::VerifierOptions,
    buf: &'b [u8],
) -> Result<SSY<'b>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::root_with_opts::<SSY<'b>>(opts, buf)
}

/// Verifies, with the given verifier options, that a buffer of
/// bytes contains a size prefixed `SSY` and returns
/// it. Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_ssy_unchecked`.
#[inline]
pub fn size_prefixed_root_as_ssy_with_opts<'b, 'o>(
    opts: &'o ::flatbuffers::VerifierOptions,
    buf: &'b [u8],
) -> Result<SSY<'b>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::size_prefixed_root_with_opts::<SSY<'b>>(opts, buf)
}

/// Assumes, without verification, that a buffer of bytes contains a SSY and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid `SSY`.
#[inline]
pub unsafe fn root_as_ssy_unchecked(buf: &[u8]) -> SSY<'_> {
    unsafe { ::flatbuffers::root_unchecked::<SSY>(buf) }
}

/// Assumes, without verification, that a buffer of bytes contains a size prefixed SSY and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid size prefixed `SSY`.
#[inline]
pub unsafe fn size_prefixed_root_as_ssy_unchecked(buf: &[u8]) -> SSY<'_> {
    unsafe { ::flatbuffers::size_prefixed_root_unchecked::<SSY>(buf) }
}

pub const SSY_IDENTIFIER: &str = "$SSY";

#[inline]
pub fn ssy_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, SSY_IDENTIFIER, false)
}

#[inline]
pub fn ssy_size_prefixed_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, SSY_IDENTIFIER, true)
}

#[inline]
pub fn finish_ssy_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<SSY<'a>>
) {
    fbb.finish(root, Some(SSY_IDENTIFIER));
}

#[inline]
pub fn finish_size_prefixed_ssy_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<SSY<'a>>
) {
    fbb.finish_size_prefixed(root, Some(SSY_IDENTIFIER));
}
